import{_ as p,a0 as o,w as d,s as g,ao as l,I as s,a1 as e,A as n,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Git 系列（七）：使用 Git 管理二進制大對象 | LCTT x X-CMD","titleTemplate":false,"description":"Git 系列（七）：使用 Git 管理二進制大對象 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Git 系列（七）：使用 Git 管理二進制大對象 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Git 系列（七）：使用 Git 管理二進制大對象 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20160815 How to manage binary blobs with Git","title":"Git 系列（七）：使用 Git 管理二進制大對象","tag":"201611","desc":""},"relativePath":"201611/20160815 How to manage binary blobs with Git.md","filePath":"[post].md"}'),r={name:"201611/20160815 How to manage binary blobs with Git.md"};function h(u,i,b,c,k,m){const a=o("Link");return d(),g("div",null,[i[24]||(i[24]=l('<h1 id="git-系列-七-使用-git-管理二進制大對象" tabindex="-1">Git 系列（七）：使用 Git 管理二進制大對象 <a class="header-anchor" href="#git-系列-七-使用-git-管理二進制大對象" aria-label="Permalink to “Git 系列（七）：使用 Git 管理二進制大對象”">​</a></h1><p>通過這系列的前六篇文章，我們已經學會使用 Git 來對文本文件進行版本控制的管理。我們不禁要問，還有二進制文件呢，也可進行進行版本控制嗎？答案是肯定的，Git 已經有了可以處理像多媒體文件這樣的二進制大對象塊（blob）的擴展。因此，今天我們會學習使用 Git 來管理所謂的二進制資產。</p><p>似乎大家都認可的事就是 Git 對於大的二進制對象文件支持得不好。要記住，二進制大對象與大文本文件是不同的。雖然 Git 對大型的文本文件版本控制毫無問題，但是對於不透明的二進制文件起不了多大作用，只能把它當作一個大的實體黑盒來提交。</p><p>設想這樣的場景，有一個另人興奮的第一人稱解密遊戲，您正在為它製作複雜的 3D 建模，源文件是以二進制格式保存的，最後生成一個 1GB 大小的的文件。您提交過一次，在 Git 源倉庫歷史中有一個 1GB 大小的新增提交。隨後，您修改了下模型人物的頭髮造型，然後提交更新，因為 Git 並不能把頭髮從頭部及模型中其餘的部分離開來，所以您只能又提交 1GB 的量。接着，您改變了模型的眼睛顏色，提交這部分更新：又是 GB 級的提交量。對一個模型的一些微小修改，就會導致三個 GB 級的提交量。對於想對一個遊戲所有資源進行版本控制這樣的規模，這是個嚴重的問題。</p><p>不同的是如 <code>.obj</code> 這種格式的文本文件，和其它類型文件一樣，都是一個提交就存儲所有更新修改狀態，不同的是 <code>.obj</code> 文件是一系列描述模型的純文本行。如果您修改了該模型並保存回 <code>.obj</code> 文件，Git 可以逐行讀取這兩個文件，然後創建一個差異版本，得到一個相當小的提交。模型越精細，提交就越小，這就是標準的 Git 用例。雖然文件本身很大，但 Git 使用覆蓋或稀疏存儲的方法來構建當前數據使用狀態的完整描述。</p><p>然而，不是所有的都是純文本的，但都要使用 Git，所以需要解決方案，並且已經出現幾個了。</p>',6)),s("p",null,[e(a,{href:"https://ostree.readthedocs.io/en/latest/"},{default:n(()=>[...i[0]||(i[0]=[t("OSTree",-1)])]),_:1}),i[1]||(i[1]=t(" 開始是作為 GNOME 項目出現的，旨在管理操作系統的二進制文件。它不適用於這裏，所以我直接跳過。",-1))]),s("p",null,[e(a,{href:"https://git-lfs.github.com/"},{default:n(()=>[...i[2]||(i[2]=[t("Git 大文件存儲",-1)])]),_:1}),i[5]||(i[5]=t("（LFS） 是放在 GitHub 上的一個開源項目，是從 git-media 項目中分支出來的。",-1)),e(a,{href:"https://github.com/alebedev/git-media"},{default:n(()=>[...i[3]||(i[3]=[t("git-media",-1)])]),_:1}),i[6]||(i[6]=t(" 和 ",-1)),e(a,{href:"https://git-annex.branchable.com/walkthrough/"},{default:n(()=>[...i[4]||(i[4]=[t("git-annex",-1)])]),_:1}),i[7]||(i[7]=t(" 是 Git 用於管理大文件的擴展。它們是對同一問題的兩種不同的解決方案，各有優點。雖然它們都不是官方的項目，但在我看來，每個都有獨到之處：",-1))]),i[25]||(i[25]=s("ul",null,[s("li",null,"git-media 是集中模式，有一個公共資產的存儲庫。你可以告訴 git-media 大文件需要存儲的位置，是在硬盤、服務器還是在雲存儲服務器，項目中的每個用户都將該位置視為大型文件的中心主存儲位置。"),s("li",null,[t("git-annex 側重於分佈模式。用户各自創建存儲庫，每個存儲庫都有一個存儲大文件的本地目錄 "),s("code",null,".git/annex"),t("。這些 annex 會定期同步，只要有需要，每個用户都可以訪問到所有的資源。除非通過 annex-cost 特別配置，否則 git-annex 優先使用本地存儲，再使用外部存儲。")])],-1)),i[26]||(i[26]=s("p",null,"對於這些，我已經在生產中使用了 git-media 和 git-annex，那麼下面會向你們概述其工作原理。",-1)),i[27]||(i[27]=s("h3",{id:"git-media",tabindex:"-1"},[t("git-media "),s("a",{class:"header-anchor",href:"#git-media","aria-label":"Permalink to “git-media”"},"​")],-1)),s("p",null,[i[9]||(i[9]=t("git-media 是使用 Ruby 語言開發的，所以首先要安裝 gem（LCTT 譯註：Gem 是基於 Ruby 的一些開發工具包）。安裝説明在",-1)),e(a,{href:"https://github.com/alebedev/git-media"},{default:n(()=>[...i[8]||(i[8]=[t("其網站",-1)])]),_:1}),i[10]||(i[10]=t("上。想使用 git-meida 的用户都需要安裝它，因為 gem 是跨平台的工具，所以在各平台都適用。",-1))]),i[28]||(i[28]=l(`<p>安裝完 git-media 後，你需要設置一些 Git 的配置選項。在每台機器上只需要配置一次。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git config filter.media.clean &quot;git-media filter-clean&quot;</span></span>
<span class="line"><span>$ git config filter.media.smudge &quot;git-media filter-smudge&quot;</span></span></code></pre></div><p>在要使用 git-media 的每個存儲庫中，設置一個屬性以將剛剛創建的過濾器結合到要您分類為“媒體（media）”的文件類型裏。別被這種術語混淆。一個更好的術語是“資產”，因為“媒體”通常的意思是音頻、視頻和照片，但您也可以很容易地將 3D 模型，烘焙和紋理等歸類為媒體。</p><p>例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;*.mp4 filter=media -crlf&quot; &gt;&gt; .gitattributes</span></span>
<span class="line"><span>$ echo &quot;*.mkv filter=media -crlf&quot; &gt;&gt; .gitattributes</span></span>
<span class="line"><span>$ echo &quot;*.wav filter=media -crlf&quot; &gt;&gt; .gitattributes</span></span>
<span class="line"><span>$ echo &quot;*.flac filter=media -crlf&quot; &gt;&gt; .gitattributes</span></span>
<span class="line"><span>$ echo &quot;*.kra filter=media -crlf&quot; &gt;&gt; .gitattributes</span></span></code></pre></div><p>當您要暫存（stage）這些類型的文件時，文件會被複制到 <code>.git/media</code> 目錄。</p><p>假設在服務器已經有了一個 Git 源倉庫，最後一步就告訴源倉庫“母艦”所在的位置，也就是，當媒體文件被推送給所有用户共享時，媒體文件將會存儲的位置。這在倉庫的 <code>.git/config</code> 文件中設置，請替換成您的用户名、主機和路徑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[git-media]</span></span>
<span class="line"><span>transport = scp</span></span>
<span class="line"><span>autodownload = false #默認為 true，拉取資源</span></span>
<span class="line"><span>scpuser = seth</span></span>
<span class="line"><span>scphost = example.com</span></span>
<span class="line"><span>scppath = /opt/jupiter.git</span></span></code></pre></div><p>如果您的服務器上 SSH 設置比較複雜，例如使用了非標準端口或非默認 SSH 密鑰文件的路徑，請使用 <code>.ssh/config</code> 為主機設置默認配置。</p><p>git-media 的使用和普通文件一樣，可以把普通文件和 blob 文件一樣對待，一樣進行 commit 操作。操作流程中唯一的不同就是，在某些時候，您應該將您的資產（或稱媒體）同步到共享存儲庫中。</p><p>當要為團隊發佈資產或自己備份資料時，請使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git media sync</span></span></code></pre></div><p>要用一個變更後的版本替換 git-media 中的文件時（例如，一個已經美聲過的音頻文件，或者一個已經完成的遮罩繪畫，或者一個已經被顏色分級的視頻文件），您必須明確的告訴 Git 更新該媒體。這將覆蓋 git-media 不會複製遠程已經存在的文件的默認設置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git update-index --really-refresh</span></span></code></pre></div><p>當您團隊的其他成員（或是您本人，在其它機器上）克隆本倉庫時，如果沒有在 <code>.git/config</code> 中把 <code>autodownload</code> 選項設置為 <code>true</code> 的話，默認是不會下載資源的。但 git-media 的一個同步命令 <code>git media sync</code> 可解決所有問題。</p><h3 id="git-annex" tabindex="-1">git-annex <a class="header-anchor" href="#git-annex" aria-label="Permalink to “git-annex”">​</a></h3><p>git-annex 的處理流程略微的有些不同，默認是使用本地倉庫的，但基本的思想都一樣。您可以從你的發行版的軟件倉庫中安裝 git-annex，或者根據需要從該網站上下載安裝。與 git-media 一樣，任何使用 git-annex 的用户都必須在其機器上安裝它。</p><p>其初始化設置比 git-media 都簡單。運行如下命令，其中替換成您的路徑，就可以在您的服務器上創建好裸存儲庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git init --bare --shared /opt/jupiter.git</span></span></code></pre></div><p>然後克隆到本地計算機，把它標記為 git-annex 的初始路徑：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone seth@example.com:/opt/jupiter.clone</span></span>
<span class="line"><span>Cloning into &#39;jupiter.clone&#39;... </span></span>
<span class="line"><span>warning: You appear to have clonedan empty repository. </span></span>
<span class="line"><span>Checking connectivity... done.</span></span>
<span class="line"><span>$ git annex init &quot;seth workstation&quot; </span></span>
<span class="line"><span>init seth workstation ok</span></span></code></pre></div><p>不要使用過濾器來區分媒體資源或大文件，您可以使用 <code>git annex</code> 命令來配置歸類大文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git annex add bigblobfile.flac</span></span>
<span class="line"><span>add bigblobfile.flac</span></span>
<span class="line"><span>(checksum) ok</span></span>
<span class="line"><span>(Recording state in Git...)</span></span></code></pre></div><p>跟普通文件一樣進行提交操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git commit -m &#39;added flac source for sound fx&#39;</span></span></code></pre></div><p>但是推送操作是不同的，因為 <code>git annex</code> 使用自己的分支來跟蹤資產。您首次推送可能需要 <code>-u</code> 選項，具體取決於您如何管理您的存儲庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git push -u origin master git-annex</span></span>
<span class="line"><span>To seth@example.com:/opt/jupiter.git</span></span>
<span class="line"><span>* [new branch] master -&gt; master</span></span>
<span class="line"><span>* [new branch] git-annex -&gt; git-annex</span></span></code></pre></div><p>和 git-media 一樣，普通的 <code>git push</code> 命令是不會拷貝資料到服務器的，僅僅只是發送了相關的消息，要真正共享文件，需要運行同步命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git annex sync --content</span></span></code></pre></div><p>如果別人已經提交了共享資源，您需要拉取它們，<code>git annex sync</code> 命令將提示您要在本地檢出你本機沒有，但在服務器上存在的資源。</p><p>git-media 和 git-annex 都非常靈活，都可以使用本地存儲庫來代替服務器，所以它們也常用於管理私有的本地項目。</p><p>Git 是一個非常強大和擴展性非常強的系統應用軟件，我們應該毫不猶豫的使用它。現在就開始試試吧！</p><hr>`,33)),s("p",null,[i[12]||(i[12]=t("via: ",-1)),e(a,{href:"https://opensource.com/life/16/8/how-manage-binary-blobs-git-part-7"},{default:n(()=>[...i[11]||(i[11]=[t("https://opensource.com/life/16/8/how-manage-binary-blobs-git-part-7",-1)])]),_:1})]),s("p",null,[i[16]||(i[16]=t("作者：",-1)),e(a,{href:"https://opensource.com/users/seth"},{default:n(()=>[...i[13]||(i[13]=[t("Seth Kenlon",-1)])]),_:1}),i[17]||(i[17]=t(" 譯者：",-1)),e(a,{href:"https://github.com/runningwater"},{default:n(()=>[...i[14]||(i[14]=[t("runningwater",-1)])]),_:1}),i[18]||(i[18]=t(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...i[15]||(i[15]=[t("wxy",-1)])]),_:1})]),s("p",null,[i[21]||(i[21]=t("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[19]||(i[19]=[t("LCTT",-1)])]),_:1}),i[22]||(i[22]=t(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...i[20]||(i[20]=[t("Linux中國",-1)])]),_:1}),i[23]||(i[23]=t(" 榮譽推出",-1))])])}const G=p(r,[["render",h]]);export{y as __pageData,G as default};
